#include <bits/stdc++.h>
using namespace std;const int V=105,S=20;int h[V],t[S],k[6],g[6],r[6],x[6],z[6];long long e(long long a,long long b,long long&x,long long&y){if(!b)return x=1,y=0,a;long long d=e(b,a%b,y,x);y-=a/b*x;return d;}int b(int a,int c,int m){int s=sqrt(m-1)+1,A=1%m,z=0,r=-1;for(int i=0;i<s;i++)h[t[z++]=1LL*c*A%m]=i,A=1LL*A*a%m;int C=1%m;for(int i=1;i<=s&&r<0;i++)if(h[C=1LL*C*A%m]>=0)r=i*s-h[C];while(z)h[t[--z]]=-1;return r;}pair<int,int> q(int a,int c,int m){if(m==1)return {0,1};int o=0,A=1%m,d=1;long long X,Y;for(;;){int z=__gcd((long long)A*a%m,(long long)m);if(z==d)break;if(A==c)return {o,-1};o++;A=1LL*A*a%m;d=z;}if(c%d)return {-1,-1};m/=d;c/=d;A/=d;e(A,m,X,Y);c=1LL*c*((X%m+m)%m)%m;int v=b(a,c,m);if(v<0)return {-1,-1};int y=b(a,1%m,m);return {v%y+o,y};}bool m(long long&a,long long&n,long long b,long long p){long long x,y,G=e(n,p,x,y),d=b-a;if(d%G)return 0;long long z=p/G,k=(__int128)(d/G)*x%z;a=(a+(__int128)n*((k+z)%z))%(n*z);n*=z;return 1;}int main(int C,char**v){ios::sync_with_stdio(0);cin.tie(0);memset(h,-1,sizeof h);int R=C>1?stoi(v[1]):1000;unsigned long long s=C>2?stoull(v[2]):1;mt19937_64 G(s);while(R--){int n=G()%5+1,d=G()%50,X=-1,M=0;long long P=0,Q=1;bool f=1;for(int i=0;i<n;i++){g[i]=G()%49+2;k[i]=G()%g[i];long long w=1%g[i];for(int j=0;j<d;j++)w=w*k[i]%g[i];r[i]=w;auto a=q(k[i],r[i],g[i]);x[i]=a.first;z[i]=a.second;if(x[i]<0)f=0;if(z[i]<0)X=x[i];M=max(M,x[i]);}long long A=-1;if(f&&X>=0){f=1;for(int i=0;i<n;i++)if((z[i]<0&&X!=x[i])||(z[i]>=0&&(X<x[i]||(X-x[i])%z[i])))f=0;if(f)A=X;}else if(f){for(int i=0;i<n;i++)if(!m(P,Q,x[i]%z[i],z[i]))f=0;if(f){if(P<M)P+=(M-P+Q-1)/Q*Q;A=P;}}long long B=-1;for(int y=0;y<=2000;y++){int i=0;for(;i<n;i++){long long w=1%g[i];for(int j=0;j<y;j++)w=w*k[i]%g[i];if(w!=r[i])break;}if(i==n){B=y;break;}}if(A!=B)return cout<<"WA\n",1;}cout<<"OK\n";}
